package dev.admutium.techmod.client.suit;
import dev.admutium.techmod.suit.*;import dev.admutium.techmod.energy.Energy;import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.Screen;import net.minecraft.client.input.*;import net.minecraft.network.chat.Component;
public final class SuitRadialScreen extends Screen {
 private boolean second;
 public SuitRadialScreen(){super(Component.literal("Системы костюма"));}
 @Override protected void init(){String[] keys=second?new String[]{"night","light","feed","magnet","vein","beacon","warp","back"}:new String[]{"flight","run","ore_scan","enemy_scan","magnet_pulse","cloak","more","close"};var d=SuitClient.wornData();for(int i=0;i<8;i++){String key=keys[i];double a=-Math.PI/2+i*Math.PI/4;int x=width/2+(int)(Math.cos(a)*115)-48,y=height/2+(int)(Math.sin(a)*70)-9;String name=switch(key){case "flight"->d.on("flight_jet")?"Ранец":d.on("flight_elytra")?"Элитра":d.on("flight_gravity")?"Гравитация":"Полёт: выкл";case "magnet_pulse"->"Притянуть [V]";case "more"->"Ещё →";case "back"->"← Назад";case "close"->"Закрыть";default->net.minecraft.network.chat.Component.translatable("suit.upgrade."+key).getString();};if(d.on(key))name="● "+name;var button=Button.builder(Component.literal(name),b->{if(key.equals("more")||key.equals("back")){second=!second;rebuildWidgets();}else if(key.equals("close"))onClose();else{SuitClient.action("toggle",key);onClose();}}).bounds(x,y,96,18).build();var upgrade=SuitUpgrade.byId(key.equals("magnet_pulse")?"magnet":key);button.active=upgrade==null||d.level(upgrade)>0;addRenderableWidget(button);}}
 @Override public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float dt){super.extractRenderState(g,mx,my,dt);int x=width/2,y=height/2;g.text(font,"КОНТУР",x-22,y-13,0xffffb85f);g.text(font,Energy.format(SuitClient.wornData().energy())+" ТЕ",x-26,y+2,0xffe4edf1);String[] names={"Ход","Добыча","Щит","Скан","Сервис"};for(int i=0;i<5;i++)g.text(font,names[i]+": "+Energy.format(SuitClient.rates[i],true)+" ТЕ/с",12+(i%3)*(width/3),height-27+(i/3)*12,0xffb7d3e0);}
 @Override public boolean keyPressed(KeyEvent e){if(e.key()==258){onClose();return true;}return super.keyPressed(e);}
 @Override public boolean isPauseScreen(){return false;}
}
